 Here's an example C++ program that meets your requirements:

```cpp
#include <iostream>
#include <string>
#include <stdexcept>

using namespace std;

void fibonacci(int n, int a = 0, int b = 1) {
    if (n <= 0) {
        throw invalid_argument("Number of sequence elements must be positive.");
    }

    if (n == 1) {
        cout << a << endl;
        return;
    }

    fibonacci(n - 1, b, a + b);
    cout << b << (n > 2 ? ", " : "");
}

int main() {
    int num1, num2, numElements;

    cout << "Enter the first number in the sequence: ";
    cin >> num1;

    if (!isdigit(num1 + '0')) {
        cerr << "Error: Invalid input. First number must be a digit." << endl;
        return 1;
    }

    cout << "Enter the second number in the sequence: ";
    cin >> num2;

    if (!isdigit(num2 + '0')) {
        cerr << "Error: Invalid input. Second number must be a digit." << endl;
        return 1;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> numElements;

    if (numElements < 0) {
        cerr << "Error: Number of sequence elements must be non-negative." << endl;
        return 1;
    }

    try {
        fibonacci(numElements, num1, num2);
    } catch (invalid_argument& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
