  fahrenheitToCelsius: (fahrenheit) => (fahrenheit - 32) * 5 / 9,
};

export const useTemperatureConversion = (initialValue, initialUnit) => {
  const [value, setValue] = useState(initialValue);
  const [unit, setUnit] = useState(initialUnit);

  const handleConvert = () => {
