```php
<?php
// Connect to the database
$servername = "localhost";
$username = "username";
$password = "password";
$dbname = "coffee_shop";
$conn = new mysqli($servername, $username, $password, $dbname);

// Check connection
if ($conn->connect_error) {
    die("Connection failed: " . $conn->connect_error);
}

// Define the product and time frame for identifying loyal customers
$product = 'coffee'; // replace with the specific product name
$start_date = date('Y-m-d', strtotime('-1 week')); // replace with the start date, e.g., last week
$end_date = date('Y-m-d'); // replace with the current date

// Execute the SQL query to get the list of loyal customers
$sql = "SELECT customers.name, COUNT(*) as purchase_count 
        FROM transactions 
        JOIN products ON transactions.product_id = products.id 
        WHERE products.name = '$product' 
        AND transactions.transaction_date BETWEEN '$start_date' AND '$end_date'
        GROUP BY transactions.customer_id 
        HAVING purchase_count >= 3";
$result = $conn->query($sql);

// Process the result and display the loyal customers
if ($result->num_rows > 0) {
    echo "<table><tr><th>Customer Name</th><th>Purchase Count</th></tr>";
    while($row = $result->fetch_assoc()) {
        echo "<tr><td>" . $row["name"] . "</td><td>" . $row["purchase_count"] . "</td></tr>";
    }
    echo "</table>";
} else {
    echo "No loyal customers found.";
}

// Close the database connection
$conn->close();
?>
```

